export function buildAMeter(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.78})}),pcb=circuit(host),input=grove(host),measurement=terminal(host),power=indicator(host);screw(host.body,[0,-16,-3.98],'back',1.35);host.add(new Component({id:'sensor',label:'AMeter appearance anchor',meta:{role:'visual-anchor',scope:'Passive appearance anchor only; no current, ADC conversion, fuse melting, protection, calibration, isolation, bus, numeric values, firmware or electrical logic'}}));const artwork=addStickers(host);host.ameterAssembly={parts,pcb,input,terminal:measurement,power,artwork};}
